CREATE     PROCEDURE [synapse_fo].[usp_Update_BUDGETRESERVATIONHEADER_PSN]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:32
	Description: Update stored procedure for BUDGETRESERVATIONHEADER_PSN from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTINGDATE] = stg.[ACCOUNTINGDATE],
		tgt.[ACCOUNTINGDISTRIBUTIONTEMPLATE] = stg.[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		tgt.[BUDGETRESERVATIONTYPE_PSN] = stg.[BUDGETRESERVATIONTYPE_PSN],
		tgt.[CANCELDATE] = stg.[CANCELDATE],
		tgt.[CARRIEDFORWARDBUDGETTRANSACTIONHEADER] = stg.[CARRIEDFORWARDBUDGETTRANSACTIONHEADER],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DEPARTMENTREFERENCE] = stg.[DEPARTMENTREFERENCE],
		tgt.[DOCUMENTNUMBER] = stg.[DOCUMENTNUMBER],
		tgt.[DOCUMENTSTATUS] = stg.[DOCUMENTSTATUS],
		tgt.[DOCUMENTTITLE] = stg.[DOCUMENTTITLE],
		tgt.[ENDDATE] = stg.[ENDDATE],
		tgt.[EXTERNALREFERENCE] = stg.[EXTERNALREFERENCE],
		tgt.[FileName] = stg.[FileName],
		tgt.[FINALIZECLOSINGDATE] = stg.[FINALIZECLOSINGDATE],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LASTSAVEDACCOUNTINGDATE] = stg.[LASTSAVEDACCOUNTINGDATE],
		tgt.[LEDGERVOUCHER] = stg.[LEDGERVOUCHER],
		tgt.[LSN] = stg.[LSN],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PSNISCORRECTION] = stg.[PSNISCORRECTION],
		tgt.[REASONTABLEREF] = stg.[REASONTABLEREF],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[RELIEVINGDOCUMENTTYPE] = stg.[RELIEVINGDOCUMENTTYPE],
		tgt.[SOURCEDOCUMENTHEADER] = stg.[SOURCEDOCUMENTHEADER],
		tgt.[STARTDATE] = stg.[STARTDATE],
		tgt.[SysRowId] = stg.[SysRowId],
		tgt.[WORKFLOWSTATUS] = stg.[WORKFLOWSTATUS]
	 FROM [synapse_fo].[BUDGETRESERVATIONHEADER_PSN] tgt
		INNER JOIN [staging_fo].[BUDGETRESERVATIONHEADER_PSN] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
